from AlgorithmImports import *
from collections import defaultdict


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0,
        }

        self.pending = {
            "A": False,
            "B": False,
        }

        self.order_strategy = {}

    def OnData(self, data: Slice):
        spy_bar = data.Bars.get(self.spy)
        aapl_bar = data.Bars.get(self.aapl)

        if spy_bar is not None:
            if self.previous_spy_close is not None:
                spy_cross_above = (
                    self.previous_spy_sma is not None
                    and self.previous_spy_close <= self.previous_spy_sma
                    and spy_bar.Close > self.spy_sma.Current.Value
                )
                spy_cross_below = (
                    self.previous_spy_sma is not None
                    and self.previous_spy_close >= self.previous_spy_sma
                    and spy_bar.Close < self.spy_sma.Current.Value
                )
            else:
                spy_cross_above = False
                spy_cross_below = False
        else:
            spy_cross_above = False
            spy_cross_below = False

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            else:
                self.aapl_red_streak = 0

            aapl_buy_reason = self.aapl_red_streak >= 3
            aapl_sell_reason = (
                self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
            )
        else:
            aapl_buy_reason = False
            aapl_sell_reason = False

        all_bars_present = all(
            symbol in data.Bars
            for symbol in self.symbols.values()
        )

        if all_bars_present:
            if (
                self.lots["A"] > 0
                and not self.pending["A"]
                and spy_cross_below
            ):
                self._submit_sell("A", self.spy, self.lots["A"])

            if (
                self.lots["B"] > 0
                and not self.pending["B"]
                and aapl_sell_reason
            ):
                self._submit_sell("B", self.aapl, self.lots["B"])

            if (
                self.lots["A"] == 0
                and not self.pending["A"]
                and self.spy_sma.IsReady
                and spy_cross_above
            ):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                quantity = int((portfolio_value * 0.40) / spy_bar.Close)
                if quantity > 0:
                    self._submit_buy("A", self.spy, quantity)

            if (
                self.lots["B"] == 0
                and not self.pending["B"]
                and self.aapl_rsi.IsReady
                and aapl_buy_reason
                and self.Portfolio.Cash >= 20000
            ):
                quantity = int(20000 / aapl_bar.Close)
                if quantity > 0:
                    self._submit_buy("B", self.aapl, quantity)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _submit_buy(self, strategy, symbol, quantity):
        self.pending[strategy] = True
        ticket = self.MarketOrder(symbol, quantity, tag=strategy + "_BUY")
        self.order_strategy[ticket.OrderId] = strategy

    def _submit_sell(self, strategy, symbol, quantity):
        if quantity <= 0:
            return

        self.pending[strategy] = True
        ticket = self.MarketOrder(symbol, -quantity, tag=strategy + "_SELL")
        self.order_strategy[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategy.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status != OrderStatus.Filled:
            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled,
            ):
                if order_event.Status != OrderStatus.PartiallyFilled:
                    self.pending[strategy] = False
            return

        filled_quantity = order_event.FillQuantity

        if filled_quantity > 0:
            self.lots[strategy] += filled_quantity
        elif filled_quantity < 0:
            self.lots[strategy] = max(
                0, self.lots[strategy] + filled_quantity
            )

        self.pending[strategy] = False
